def sig(file,arm,normalize):
 tree=ast.parse(file.read_text());nodes=[]
 for name in ['batch','is_block','forward','loss_value','rng_state','restore_rng']:nodes.append(next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name==name))
 if arm in ('gru','transformer'):
  cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name==('TerminalGRU' if arm=='gru' else 'TerminalTransformer'))
  nodes.extend(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name in ('__init__','forward'))
 for n in nodes:
  if n.body and isinstance(n.body[0],ast.Expr) and isinstance(n.body[0].value,ast.Constant) and isinstance(n.body[0].value.value,str):n.body=n.body[1:]
  if normalize:
   for child in ast.walk(n):
    if hasattr(child,'type_params'):
     assert child.type_params==[];del child.type_params
 return hashlib.sha256('\n'.join(ast.dump(n,include_attributes=False) for n in nodes).encode()).hexdigest()
